<?php
namespace App\Console\Commands; use App\Models\AttendanceMachine; use App\Services\Attendance\ZktecoReadOnlySyncService; use Illuminate\Console\Command;
class SyncAttendanceDevices extends Command{protected $signature='attendance:sync-devices {--device=}';protected $description='Read attendance logs from enabled LAN devices without changing device state';public function handle(ZktecoReadOnlySyncService $service):int{$q=AttendanceMachine::where('is_active',true)->where('automatic_sync_enabled',true);if($this->option('device'))$q->whereKey($this->option('device'));$q->each(function($d)use($service){try{$b=$service->sync($d);$this->info("{$d->device_name}: {$b->imported_count} imported");}catch(\Throwable $e){$this->error("{$d->device_name}: {$e->getMessage()}");}});return self::SUCCESS;}}
